import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    # Quick counters
    opp_c = 0
    for x in op:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c

    my_c = 0
    for x in me:
        if x == 'C':
            my_c += 1
    my_d = n - my_c

    # Immediate co-operative opening, but strong early retaliation.
    if n <= 2:
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # Recent windows
    rl = 8 if n >= 8 else n
    recent_op = op[-rl:]
    recent_me = me[-rl:]
    recent_opp_c = 0
    for x in recent_op:
        if x == 'C':
            recent_opp_c += 1
    recent_opp_d = rl - recent_opp_c

    recent_my_c = 0
    for x in recent_me:
        if x == 'C':
            recent_my_c += 1
    recent_my_d = rl - recent_my_c

    opp_rate = opp_c / float(n)
    recent_rate = recent_opp_c / float(rl)

    last_op = op[-1]
    last_me = me[-1]

    # Run lengths at end
    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break

    run_c = 0
    for x in reversed(op):
        if x == 'C':
            run_c += 1
        else:
            break

    # Endgame: exploit unless opponent is very cooperative and we're aligned.
    remaining = 100 - n
    if remaining <= 3:
        if opp_rate >= 0.9 and recent_opp_d == 0:
            return 'C'
        return 'D'

    # Opponent almost always cooperative: exploit in midgame, but keep some C
    if n >= 6 and opp_rate >= 0.9 and recent_opp_d <= 1:
        # If late, defect for max payoff; if early, sometimes test cooperation.
        if remaining <= 15:
            return 'D'
        if rng.random() < 0.65:
            return 'D'
        return 'C'

    # Opponent almost always defective: defect mostly, rare probe
    if n >= 5 and opp_rate <= 0.15:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Defend against sustained defection runs
    if run_d >= 3:
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Tit-for-tat core with forgiveness and targeted exploitation.
    if last_op == 'D':
        # If opponent was cooperative before this defection, forgive once.
        if recent_rate >= 0.75 and run_d == 1 and n >= 4:
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        # If they keep defecting, retaliate.
        if run_d >= 2:
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # last_op == 'C'
    # If opponent just cooperated but has a bad history, be cautious.
    if opp_rate < 0.35:
        if rng.random() < 0.45:
            return 'D'
        return 'C'

    # Strong cooperative phase: occasionally defect to test / exploit.
    if run_c >= 4:
        if n > 30 and remaining > 10 and rng.random() < 0.12:
            return 'D'
        return 'C'

    if run_c >= 2:
        if n > 50 and remaining > 5 and rng.random() < 0.07:
            return 'D'
        return 'C'

    # Default cooperate when opponent seems reasonably cooperative.
    if recent_rate >= 0.6:
        return 'C'

    # Mixed opponent: probabilistic caution.
    if rng.random() < 0.35:
        return 'D'
    return 'C'
